/* Combine UTF-8 into 32-bit Unicode. */
uint32_t
utf8_combine(const struct utf8_data *utf8data)
{
	uint32_t value;

	value = 0xff;
	switch (utf8data->size) {
	case 1:
		value = utf8data->data[0];
		break;
	case 2:
		value = utf8data->data[1] & 0x3f;
		value |= ((uint32_t) (utf8data->data[0] & 0x1f)) << 6;
		break;
	case 3:
		value = utf8data->data[2] & 0x3f;
		value |= ((uint32_t) (utf8data->data[1] & 0x3f)) << 6;
		value |= ((uint32_t) (utf8data->data[0] & 0x0f)) << 12;
		break;
	case 4:
		value = utf8data->data[3] & 0x3f;
		value |= ((uint32_t) (utf8data->data[2] & 0x3f)) << 6;
		value |= ((uint32_t) (utf8data->data[1] & 0x3f)) << 12;
		value |= ((uint32_t) (utf8data->data[0] & 0x07)) << 18;
		break;
	}
	return (value);
}

