/* Lookup width of UTF-8 data in tree. */
u_int
utf8_width(const struct utf8_data *utf8data)
{
	uint32_t value;
#ifndef UTF8_WIDTH_CODE
	struct utf8_width_entry *item;
#endif

	value = utf8_combine(utf8data);
#ifdef UTF8_WIDTH_CODE
	return (utf8_width_lookup(value));
#else
	item = utf8_width_root;
	while (item != NULL) {
		if (value < item->first)
			item = item->left;
		else if (value > item->last)
			item = item->right;
		else
			return (item->width);
	}
	return (1);
#endif
}
